$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$main=(git rev-parse origin/main | Out-String).Trim()
$active=@()
$wtLines=@(git worktree list --porcelain)
foreach($line in $wtLines){
 if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) }
}
$deleted=@(); $preserved=@()
$refs=@(git for-each-ref --format='%(refname:short)' refs/remotes/origin)
foreach($ref in $refs){
 if((-not $ref.StartsWith('origin/')) -or $ref -in @('origin/main','origin/HEAD','origin/heaven-bridge')){continue}
 $branch=$ref.Substring(7)
 if($branch -in $active){ $preserved += [ordered]@{branch=$branch;reason='active-worktree'}; continue }
 git merge-base --is-ancestor $ref origin/main 2>$null
 if($LASTEXITCODE -eq 0){
   git push origin --delete $branch
   if($LASTEXITCODE -eq 0){$deleted += [ordered]@{branch=$branch;proof='ancestor-of-main'}} else {$preserved += [ordered]@{branch=$branch;reason='delete-failed'}}
   continue
 }
 $ch=@(git cherry origin/main $ref 2>$null)
 $plus=@($ch | Where-Object { $_.StartsWith('+') })
 if($plus.Count -eq 0){
   git push origin --delete $branch
   if($LASTEXITCODE -eq 0){$deleted += [ordered]@{branch=$branch;proof='patch-equivalent-to-main'}} else {$preserved += [ordered]@{branch=$branch;reason='delete-failed'}}
 } else {
   $preserved += [ordered]@{branch=$branch;reason='unique-patches';unique=$plus.Count}
 }
}
git fetch origin --prune | Out-Null
[ordered]@{main=$main;deleted=$deleted;preserved=$preserved;active_worktrees=$active} | ConvertTo-Json -Depth 5
